// Lumi design tokens → per-platform codegen. One source (tokens/**), five targets:
// TS for the Expo app (src/theme/tokens.generated.ts, committed), plus JS / CSS /
// iOS-Swift / Android-Compose so a future desktop/native surface (ADR 0001 §2.4a)
// stays token-faithful with no drift.
import StyleDictionary from "style-dictionary";

const HEADER =
  "/* GENERATED by design/style-dictionary.config.js from design/tokens/*.json — do not edit.\n" +
  "   Regenerate: cd design && npm run build */\n";

/** Flat maps the app reads: palette (family+step), mood, light/dark colors, space, radius, motion. */
StyleDictionary.registerFormat({
  name: "typescript/lumi",
  format: ({ dictionary }) => {
    const groups = {
      palette: {},
      mood: {},
      lightColors: {},
      darkColors: {},
      space: {},
      radius: {},
      motion: {},
    };
    for (const token of dictionary.allTokens) {
      const [root, ...rest] = token.path;
      const value = token.value;
      if (root === "color") groups.palette[rest.join("")] = value;
      else if (root === "mood") groups.mood[rest.join("")] = value;
      else if (root === "theme" && rest[0] === "light")
        groups.lightColors[rest.slice(1).join("")] = value;
      else if (root === "theme" && rest[0] === "dark")
        groups.darkColors[rest.slice(1).join("")] = value;
      else if (root in groups) groups[root][rest.join("")] = value;
    }
    const emit = (name, obj) =>
      `export const ${name} = {\n` +
      Object.entries(obj)
        .map(([k, v]) => `  ${k}: ${typeof v === "number" ? v : JSON.stringify(v)},`)
        .join("\n") +
      `\n} as const;\n`;
    return (
      HEADER +
      "\n" +
      Object.entries(groups)
        .map(([name, obj]) => emit(name, obj))
        .join("\n")
    );
  },
});

export default {
  source: ["tokens/**/*.json"],
  platforms: {
    ts: {
      transformGroup: "js",
      buildPath: "../src/theme/",
      files: [{ destination: "tokens.generated.ts", format: "typescript/lumi" }],
    },
    js: {
      transformGroup: "js",
      buildPath: "build/js/",
      files: [{ destination: "tokens.js", format: "javascript/es6" }],
    },
    css: {
      transformGroup: "css",
      buildPath: "build/css/",
      files: [{ destination: "tokens.css", format: "css/variables" }],
    },
    ios: {
      transformGroup: "ios-swift",
      buildPath: "build/ios/",
      files: [
        {
          destination: "LumiTokens.swift",
          format: "ios-swift/enum.swift",
          options: { className: "LumiTokens" },
        },
      ],
    },
    compose: {
      transformGroup: "compose",
      buildPath: "build/compose/",
      files: [
        {
          destination: "LumiTokens.kt",
          format: "compose/object",
          options: { className: "LumiTokens", packageName: "app.lumi.tokens" },
        },
      ],
    },
  },
};
